"""Helper utilities."""

def roman_to_int(s: str) -> int:
    """Convert a Roman numeral to an integer."""
    roman_map = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}

    # Validate input: Any character outside I, V, X, L, C, D, M must raise ValueError
    for char in s:
        if char not in roman_map:
            raise ValueError(f"Invalid Roman numeral character: {char}")

    total = 0
    prev_value = 0
    # Process from right to left to handle subtractive pairs easily
    for char in reversed(s):
        value = roman_map[char]
        if value < prev_value:
            total -= value
        else:
            total += value
        prev_value = value
    return total
